use rig::tool::ToolExecutionError;


#[derive(Debug, thiserror::Error)]
enum LookupError {
    #[error("no customer with id {0}")]
    NotFound(String),
    #[error("database unreachable at {0}")]
    Database(String),
}


#[derive(Deserialize)]
struct LookupArgs {
    id: String,
}


struct LookupCustomer;


impl Tool for LookupCustomer {
    const NAME: &'static str = "lookup_customer";
    type Args = LookupArgs;
    type Output = String;
    type Error = LookupError;


    fn description(&self) -> String {
        "Look up a customer by id".to_string()
    }


    fn parameters(&self) -> serde_json::Value {
        json!({
            "type": "object",
            "properties": { "id": { "type": "string" } },
            "required": ["id"]
        })
    }


    fn map_error(&self, error: LookupError) -> ToolExecutionError {
        match error {
            // Safe and useful for the model: say what went wrong.
            LookupError::NotFound(_) => ToolExecutionError::not_found(error.to_string()),
            // The message names an internal host: log it, tell the model less.
            LookupError::Database(_) => ToolExecutionError::network(error.to_string())
                .with_model_feedback("the customer database is unavailable; try again later")
                .with_code("DB_DOWN")
                .with_source(error),
        }
    }


    async fn call(&self, _ctx: &mut ToolContext, args: LookupArgs) -> Result<String, LookupError> {
        Err(LookupError::NotFound(args.id))
    }
}

use rig::tool::ToolExecutionError;


/// The signed-in user. Set by the host, never by the model.
#[derive(Serialize, Deserialize, rig::ContextValue)]
struct UserId(String);


/// Host-only metadata the tool reports back about its call.
#[derive(Serialize, Deserialize, rig::ContextValue)]
#[context(key = "orders.rows_read")]
struct RowsRead(usize);


#[derive(Deserialize)]
struct NoArgs {}


struct ListOrders;


impl Tool for ListOrders {
    const NAME: &'static str = "list_orders";
    type Args = NoArgs;
    type Output = Vec<String>;
    type Error = ToolExecutionError;


    fn description(&self) -> String {
        "List the signed-in user's recent orders".to_string()
    }


    fn parameters(&self) -> serde_json::Value {
        json!({ "type": "object", "properties": {} })
    }


    async fn call(&self, ctx: &mut ToolContext, _args: NoArgs) -> Result<Vec<String>, ToolExecutionError> {
        let user = ctx.require::<UserId>()?;
        let orders = vec![format!("order #1001 for {}", user.0)];
        ctx.insert_result(RowsRead(orders.len()))?;
        Ok(orders)
    }
}

