use rig::completion::CompletionRequest;
use rig::message::{AssistantContent, Message};
use rig::tool::ToolSet;


let model = OpenAI::from_env()?.completion(openai::GPT_5_5);
let mut tools = ToolSet::default();
tools.add_tool(ThinkTool);


let request = CompletionRequest::new(Message::user("Think about 2 + 2, then answer."))
    .tools(tools.tool_definitions());
let response = model.call(request).await?;


for content in &response.choice {
    if let AssistantContent::ToolCall(call) = content {
        let args = serde_json::to_string(&call.function.arguments)?;
        let result = tools
            .execute(&call.function.name, args, &mut ToolContext::new())
            .await;
        println!("{} -> {}", call.function.name, result.output().render());
    }
}
